import {t,html,getLanguage,setLanguage,locale,languageSelect,syncLanguageControls,captureStaticCopy,normalizeSearch,recipeSearchText} from './i18n.js';
import {foods,recipes,slots,times,spanishFoods,shoppingHints,mealPhotos,portionGroups,productSources} from './data.js';
import {localDate,parseDate,addDays,weekday,weekStart,dateRange,round,nutrition,sumNutrition,isTraining,dayTarget,planDay,basket,basketKey,resizeWeight,defaultState,activeProfile,shoppingProfiles,householdTarget,householdRecipe,portionForRecipe,estimateCalories,makeProfile,migrateState,validateState,recipeAmounts,setRecipeAmounts,searchReplacements,setMeal,removeProfile,restoreProfile} from './engine.js';
import {foodsFor,spanishFor,recipesFor,parseIngredientText,recipeMacros,createCustomRecipe} from './custom-recipes.js';
import {startAccountController} from './session.js';
import {draftRecipeWithAI} from './recipe-ai.js';
const icons={
 leaf:'<path d="M5 19C5 8 10 4 20 4c0 10-4 15-15 15Z"/><path d="m3 21 10-10"/>',
 day:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 9h8M8 13h5M8 17h3"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',
 book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4V4Zm9 3a3 3 0 0 1 3-3h5v14h-4a4 4 0 0 0-4 3"/>',
 basket:'<path d="M3 9h18l-2 11H5L3 9Zm4 0 4-6m6 6-4-6M9 13v3m6-3v3"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3h.01"/>',
 fire:'<path d="M12 3c1 5 6 5 6 11a6 6 0 0 1-12 0c0-3 2-5 3-6 0 3 1 4 2 4 2-3-1-5 1-9Z"/>',
 protein:'<path d="m5 15 10-10m-9 5 8 8M3 13l8 8m2-18 8 8M3 17l4 4M17 3l4 4"/>',
 drop:'<path d="M12 3C9 8 5 11 5 15a7 7 0 0 0 14 0c0-4-4-7-7-12Z"/>',
 carbs:'<path d="M12 21V3m0 6C6 9 5 6 5 4c5 0 7 2 7 5Zm0 6c-6 0-7-3-7-5 5 0 7 2 7 5Zm0-6c6 0 7-3 7-5-5 0-7 2-7 5Zm0 6c6 0 7-3 7-5-5 0-7 2-7 5Z"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 swap:'<path d="M3 7h16m-3-3 3 3-3 3M21 17H5m3-3-3 3 3 3"/>',
 left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',
 calc:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 7h6M9 12h.01M15 12h.01M9 16h.01M15 16h.01"/>',
 spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
 download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',
 copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
 play:'<path d="m9 6 10 6-10 6V6Z"/>',
 logout:'<path d="M9 4H4v16h5M14 8l4 4-4 4M8 12h10"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>'
};
const ico=(name)=>html`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const img=meal=>mealPhotos[meal.image].url;
const n=v=>Math.round(v).toLocaleString(locale());
const grams=g=>g>=1000?html`${(g/1000).toLocaleString(locale(),{maximumFractionDigits:2})} кг`:html`${g.toLocaleString(locale(),{maximumFractionDigits:1})} г`;
const fullDate=key=>parseDate(key).toLocaleDateString(locale(),{day:'numeric',month:'long'});
const shortDate=key=>parseDate(key).toLocaleDateString(locale(),{day:'numeric',month:'short'});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const weekDays=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
const names={day:'Мой день',plan:'План питания',recipes:'Рецепты',basket:'Корзина',settings:'Настройки'};
const storageKey='teply-ration-v1';
let state=defaultState(), storageOk=true,accountController=null,accountUser=null,cloudStatus='local',recipeDraft=null,editorEpoch=0;
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved)state=migrateState(saved);}catch{storageOk=false;}
let date=localDate(),view=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'day',planScope='week',basketScope='week',recipeFilter='all',searchTerm='',recipeScope='family',pendingRemoval=null,replacementContext=null,replacementQuery='';
let toastTimer;
const $=selector=>document.querySelector(selector);
const person=()=>activeProfile(state);
const selectedPeople=()=>shoppingProfiles(state);
const catalog=()=>foodsFor(state);
const recipeList=()=>recipesFor(state);
const localizedFood=id=>state.customFoods?.[id]?catalog()[id][0]:t(catalog()[id][0]);
const mealText=(meal,field)=>meal.custom?meal[field]:t(meal[field]);
const foodName=id=>esc(localizedFood(id));
const foodLabel=id=>html`${localizedFood(id)} (${spanishFor(state,id)})`;
function photo(meal,dialog=false){return html`<div class="${dialog?'dialog-image':'meal-image'}"><span class="photo-fallback">${ico('leaf')}<span>${esc(mealText(meal,'title'))}</span></span><img src="${img(meal)}" alt="${esc(mealText(meal,'title'))} — иллюстрация блюда" ${dialog?'':'loading="lazy"'} referrerpolicy="no-referrer">${dialog?'':html`<span class="meal-tag">${t(slots[meal.slot])} · ${meal.servingTime||times[meal.slot]}</span>`}</div>`;}
function profileBar(){return html`<div class="household-bar"><div class="profile-switch" aria-label="Выбор личного профиля">${state.profiles.map(p=>html`<div class="person-tab ${p.id===person().id?'active':''}"><button class="person-chip ${p.id===person().id?'active':''}" data-person="${p.id}" aria-pressed="${p.id===person().id}"><span class="person-initial">${esc(p.name.slice(0,1))}</span><span>${esc(p.name)}<small>${n(dayTarget(date,state,p))} ккал${p.inShopping?'':t(' · вне корзины')}</small></span></button><button class="remove-person" data-remove-person="${p.id}" aria-label="Удалить участника ${esc(p.name)}" title="${state.profiles.length===1?t('Нужно оставить хотя бы одного участника'):t('Удалить участника')}" ${state.profiles.length===1?'disabled':''}>×</button></div>`).join('')}<button class="add-person" id="addPerson" aria-label="Добавить человека" ${state.profiles.length>=8?'disabled':''}>+</button></div><button class="family-link" data-nav="settings">${ico('settings')} Настроить профили</button></div>`;}
function familySummary(){return html`<div class="family-summary"><div class="family-summary-title">В корзине на ${shortDate(date)}</div>${selectedPeople().map(p=>html`<div class="family-member"><span>${esc(p.name)}</span><b>${n(dayTarget(date,state,p))} <small>ккал</small></b></div>`).join('')||t('<p class="muted">Выбери участников в настройках</p>')}<div class="family-member family-total"><span>Всего · ${selectedPeople().length} чел.</span><b>${n(householdTarget(date,state))} <small>ккал</small></b></div></div>`;}
function persist(){try{if(accountController)storageOk=accountController.persist(state);else{localStorage.setItem(storageKey,JSON.stringify(state));storageOk=true;}}catch{storageOk=false;}updateSave();}
function updateSave(){const el=$('#saveStatus');const labels={local:t('Сохранено на устройстве'),saved:t('Сохранено в аккаунте'),saving:t('Синхронизация…'),offline:t('Нет связи · изменения на устройстве'),conflict:t('Конфликт версий · открой настройки'),'signed-out':t('Войди в аккаунт')};el.textContent=storageOk?(labels[cloudStatus]||labels.local):t('Не удалось сохранить на устройстве');el.classList.toggle('storage-warning',!storageOk||['offline','conflict'].includes(cloudStatus));}

function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function navigate(next){view=next;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
function heading(title,subtitle){return html`<div class="page-heading"><div><div class="eyebrow">ПИТАНИЕ В ТВОЁМ РИТМЕ</div><h1>${title}</h1><p>${subtitle}</p></div>${dateControl()}</div>`;}
function dateControl(){return html`<div class="date-control"><button data-step="-1" aria-label="Предыдущий период">${ico('left')}</button><input type="date" id="selectedDate" value="${date}" aria-label="Выбрать дату"><button data-step="1" aria-label="Следующий период">${ico('right')}</button></div>`;}
function tabs(active,kind){return html`<div class="segmented" aria-label="Период">${[['day',t('День')],['week',t('Неделя')],['month',t('Месяц')]].map(([id,title])=>html`<button data-${kind}="${id}" class="${active===id?'active':''}" aria-pressed="${active===id}">${t(title)}</button>`).join('')}</div>`;}
function macroStats(){const meals=planDay(date,state),planned=sumNutrition(meals.map(m=>m.macros)),logged=Object.entries(person().logged).filter(([key])=>key.startsWith(html`${date}:`)).map(([,entry])=>entry.macros),eaten=sumNutrition(logged);return html`<div class="stats-row">${[t('Калории'),t('Белки'),t('Жиры'),t('Углеводы')].map((label,i)=>html`<div class="stat"><div class="stat-top"><span>${label}</span>${ico(['fire','protein','drop','carbs'][i])}</div><div class="stat-value">${n(planned[i])}<small>${i?t('г'):t('ккал')}</small></div><div class="stat-foot">съедено ${n(eaten[i])} ${i?t('г'):t('ккал')} из плана</div><div class="tiny-bar"><span style="width:${Math.min(100,eaten[i]/planned[i]*100)}%"></span></div></div>`).join('')}</div>`;}
function dayStrip(){return html`<div class="day-strip">${dateRange(date).map(key=>html`<button class="day-chip ${date===key?'active':''}" data-date="${key}" aria-label="${fullDate(key)}${isTraining(key,state)?t(', тренировка'):''}" aria-pressed="${date===key}"><small>${t(weekDays[weekday(key)])}</small><strong>${parseDate(key).getDate()}</strong><span class="training-dot ${isTraining(key,state)?'':'empty'}"></span></button>`).join('')}</div>`;}
function mealCard(meal,library=false){const key=html`${date}:${meal.slot}`,entry=person().logged[key],logged=!!entry;return html`<article class="meal-card"><button class="recipe-open" data-recipe="${meal.id}" data-recipe-date="${date}" aria-label="Рецепт: ${esc(mealText(meal,'title'))}">${photo(meal)}<div class="meal-body"><div class="meal-label">${ico('clock')} ${meal.time} мин${meal.custom?t('<span> · Мой рецепт</span>'):''}${meal.portionGroup==='overnight'?t('<span> · С вечера</span>'):''}${meal.video?html`<span> · ${meal.search?t('Видео в поиске'):t('Видеорецепт')}</span>`:''}</div><h3>${esc(mealText(meal,'title'))}</h3><div class="meal-meta"><strong>${n(meal.macros[0])} ккал</strong><span>Б ${n(meal.macros[1])}</span><span>Ж ${n(meal.macros[2])}</span><span>У ${n(meal.macros[3])}</span></div></div></button><div class="meal-actions">${library?html`<button class="meal-check" data-use="${meal.id}">${ico('calendar')} В меню ${shortDate(date)}</button><button class="swap" data-recipe="${meal.id}">Рецепт</button>`:html`<button class="meal-check ${logged?'checked':''}" data-log="${meal.slot}" aria-pressed="${logged}"><span class="check-box">${logged?ico('check'):''}</span>${logged?(entry.id===meal.id?t('Съедено'):t('Съеден другой вариант')):t('Отметить приём')}</button><button class="swap" data-swap="${meal.slot}" aria-label="Заменить: ${esc(mealText(meal,'title'))}">${ico('swap')} Заменить</button>`}</div></article>`;}
function calculator(){const p=person();return html`<section class="calculator"><div class="panel-title"><h3>Твои ориентиры</h3>${ico('calc')}</div><p class="panel-description">Порции для <b>${esc(p.name)}</b>.<br>Корзина суммирует выбранные профили.</p><label class="block calculator-person-label" for="calculatorPerson">Личный профиль</label><select id="calculatorPerson" class="profile-select">${state.profiles.map(p=>html`<option value="${p.id}" ${p.id===person().id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${p.demo?t('<div class="profile-demo">Цель калорий — пример, укажи свою</div>'):''}<div class="calculator-field"><div class="field-top"><label for="weightRange">Текущий вес</label><div class="number-wrap"><input id="weightNumber" type="number" min="40" max="180" step="0.5" value="${p.weight}" aria-label="Текущий вес в килограммах"><span>кг</span></div></div><input type="range" id="weightRange" min="40" max="180" step="0.5" value="${p.weight}" aria-label="Текущий вес"><div class="range-labels"><span>40 кг</span><span>180 кг</span></div></div><div class="calculator-field"><div class="field-top"><label for="kcalRange">Базовая цель на день</label><div class="number-wrap"><input id="kcalNumber" type="number" min="1200" max="5000" step="10" value="${p.kcal}" aria-label="Калории в день"><span>ккал</span></div></div><input type="range" id="kcalRange" min="1200" max="5000" step="10" value="${p.kcal}" aria-label="Калории в день"><div class="range-labels"><span>1 200 ккал</span><span>5 000 ккал</span></div></div><label class="toggle-row"><input id="linkWeight" type="checkbox" ${p.linkWeight?'checked':''}><span>Менять мою цель пропорционально весу</span></label><div class="calculation-total"><span>${esc(p.name)} · ${shortDate(date)}${isTraining(date,state)&&p.bonus?html`<br><small>включая +${p.bonus} за тренировку</small>`:''}</span><b>${n(dayTarget(date,state))} <small>ккал</small></b></div>${familySummary()}<button class="secondary calculator-details" data-nav="settings">Рост, возраст и оценка калорий</button><div class="live-hint">${ico('spark')}<span>Одинаковые блюда, личные порции.<br>Общие граммовки — внутри рецепта.</span></div></section>`;}
function miniBasket(){const dates=dateRange(date),rows=basket(dates,state),main=rows.filter(r=>['chicken','turkey','potato','oats'].includes(r.id));return html`<section class="mini-basket"><div class="panel-title"><h3>Корзина на неделю</h3><span>${ico('basket')}</span></div><p>${fullDate(dates[0])} — ${fullDate(dates[6])} · ${selectedPeople().length} чел. · ${rows.length} продуктов</p>${main.map(r=>html`<div class="mini-food"><span>${esc(localizedFood(r.id))}<small lang="es">(${esc(r.spanish)})</small></span><span>${grams(r.grams)}</span></div>`).join('')}<button class="primary" data-nav="basket">Открыть список покупок</button></section>`;}
function waterCard(){const water=person().water[date]||0;return html`<section class="water-card"><div class="water-top"><h3>${ico('drop')} Вода за день</h3><span>${(water/1000).toLocaleString(locale())} л</span></div><p>Удобная отметка, без заданной нормы.</p><div class="water-actions"><button data-water="250">+ 250 мл</button><button data-water="-250" aria-label="Убрать 250 миллилитров">−</button><button data-water="0">Сбросить</button></div></section>`;}
function renderDay(){return html`${heading(html`Забота о себе — каждый день<span class="headline-leaf">${ico('leaf')}</span>`,t('Твой план питания, любимые блюда и немного порядка.'))}<div class="dashboard-grid"><div>${macroStats()}<div class="section-top"><div class="section-title"><h2>Меню на день</h2></div>${tabs('day','period')}</div>${dayStrip()}<div class="daily-title"><span>${parseDate(date).toLocaleDateString(locale(),{weekday:'long',day:'numeric',month:'long'})}</span><button class="training-pill" data-toggle-training aria-label="Изменить тип дня">${ico(isTraining(date,state)?'protein':'sun')}${isTraining(date,state)?t('Тренировочный'):t('День отдыха')}</button></div><div class="meal-grid">${planDay(date,state).map(m=>mealCard(m)).join('')}</div><p class="subtle-info">В карточках — порция для <b>${esc(person().name)}</b>. Открой рецепт, чтобы увидеть граммовки для каждого и общий вес для приготовления. Фото иллюстративные.</p></div><aside class="side-stack">${calculator()}${miniBasket()}${waterCard()}</aside></div>`;}
function renderPlan(){const scope=planScope,dates=dateRange(date,scope),totals=dates.map(key=>sumNutrition(planDay(key,state).map(m=>m.macros))),sum=sumNutrition(totals);return html`${heading(scope==='month'?t('Месяц с хорошим планом'):t('Твоя неделя, без суеты'),html`Личное меню: ${esc(person().name)}. Блюда общие, порции у каждого свои.`)}<div class="toolbar">${tabs(scope,'period')}<div class="toolbar-group"><button class="secondary" data-training-settings>${ico('protein')} Дни тренировок</button><button class="primary" data-basket-period="${scope}">${ico('basket')} Продукты на ${scope==='month'?t('месяц'):t('неделю')}</button></div></div><div class="top-stats"><div class="top-stat"><small>Период плана</small><b>${dates.length} <span>дней</span></b></div><div class="top-stat"><small>Средняя калорийность · ${esc(person().name)}</small><b>${n(sum[0]/dates.length)} <span>ккал / день</span></b></div><div class="top-stat"><small>Тренировочные дни</small><b>${dates.filter(d=>isTraining(d,state)).length} <span>за период</span></b></div></div>${scope==='month'?renderMonth(dates):html`<div class="week-list">${dates.map(key=>html`<article class="week-row"><button class="week-day" data-open-day="${key}"><strong>${t(weekDays[weekday(key)])}, ${fullDate(key)}</strong><small>${n(dayTarget(key,state))} ккал</small>${isTraining(key,state)?html`<span class="training-pill">${ico('protein')} Тренировка</span>`:''}</button>${planDay(key,state).map(meal=>html`<button class="week-meal" data-recipe="${meal.id}" data-recipe-date="${key}"><small>${t(slots[meal.slot])}</small><b>${esc(mealText(meal,'title'))}</b><span>${n(meal.macros[0])} ккал</span></button>`).join('')}</article>`).join('')}</div>`}<p class="subtle-info">Базовое меню повторяется по дням недели. Замены общие для всей семьи и сохраняются по датам. Тренировки и калорийность — отдельные для каждого профиля.</p>`;}
function renderMonth(dates){return html`<h2 style="margin-bottom:15px">${parseDate(date).toLocaleDateString(locale(),{month:'long',year:'numeric'})}</h2><div class="month-grid">${weekDays.map(day=>html`<div class="month-label">${t(day)}</div>`).join('')}${Array.from({length:weekday(dates[0])},()=>'<div></div>').join('')}${dates.map(key=>html`<button class="month-day ${key===date?'active':''}" data-open-day="${key}" aria-label="Открыть ${fullDate(key)}"><strong>${parseDate(key).getDate()} ${isTraining(key,state)?ico('protein'):''}</strong><small>${esc(mealText(planDay(key,state)[1],'title'))}</small><span>${n(dayTarget(key,state))} ккал</span></button>`).join('')}</div>`;}
function libraryMeals(){return recipeList().filter(r=>(recipeFilter==='all'||r.slot===Number(recipeFilter))&&normalizeSearch(recipeSearchText(r,state)).includes(normalizeSearch(searchTerm))).map(r=>portionForRecipe(r.id,date,state));}
function renderRecipes(){return html`${heading(t('Блюда, к которым хочется вернуться'),t('Состав, граммовки и понятные шаги. Ничего лишнего.'))}<div class="recipe-create-bar"><p>Твои блюда тоже могут стать частью плана.</p><button class="primary" id="newRecipe">+ Добавить свой рецепт</button></div><div class="toolbar"><div class="filter-chips">${[['all',t('Все блюда')],...slots.map((s,i)=>[i,s])].map(([id,title])=>html`<button data-filter="${id}" class="${String(recipeFilter)===String(id)?'active':''}">${t(title)}</button>`).join('')}</div><label class="search">${ico('search')}<input id="recipeSearch" placeholder="Найти блюдо…" value="${esc(searchTerm)}" aria-label="Поиск рецептов"></label></div><div class="recipes-grid" id="recipesGrid">${recipeResults()}</div><p class="subtle-info">Порции в каталоге соответствуют выбранной дате. При замене блюда всё меню дня пересчитывается до заданной калорийности.</p>`;}
function recipeResults(){const meals=libraryMeals();return meals.length?meals.map(m=>mealCard(m,true)).join(''):t('<div class="empty-state">Такого блюда пока нет. Попробуй другой запрос.</div>');}
function renderBasket(){const dates=dateRange(date,basketScope),rows=basket(dates,state),people=selectedPeople(),bought=rows.filter(r=>state.bought[basketKey(dates,r)]).length,groups=[...new Set(rows.map(r=>r.category))],total=rows.reduce((t,r)=>t+r.grams,0);return html`${heading(t('Всё для вашего меню'),t('Общая корзина с испанскими названиями для покупок в Сарагосе.'))}<div class="toolbar">${tabs(basketScope,'basket-scope')}<span class="muted" style="font-size:12px">${fullDate(dates[0])}${dates.length>1?html` — ${fullDate(dates.at(-1))}`:''}</span></div><section class="shopping-people"><div><h3>Кто в корзине</h3><p>У каждого своя калорийность. Общие продукты складываются.</p></div><div class="shopping-people-checks">${state.profiles.map(p=>html`<label><input type="checkbox" data-shopping-person="${p.id}" ${p.inShopping?'checked':''}><span>${esc(p.name)}<small>${n(dayTarget(date,state,p))} ккал · выбранный день</small></span></label>`).join('')}</div></section><div class="basket-grid"><div>${rows.length?groups.map(group=>html`<section class="basket-group"><h3>${t(group)}</h3>${rows.filter(r=>r.category===group).map(r=>{const checked=!!state.bought[basketKey(dates,r)];return html`<div class="basket-product"><label class="basket-item ${checked?'purchased':''}"><input type="checkbox" data-buy="${r.id}" ${checked?'checked':''}><span class="food-name">${esc(localizedFood(r.id))}<span class="spanish-name" lang="es">(${esc(r.spanish)})</span></span><span class="quantity">${grams(r.grams)}</span></label><details class="product-detail"><summary>По людям${shoppingHints[r.id]?t(' и подсказка для покупки'):''}</summary><div>${people.map(p=>html`<span>${esc(p.name)}: <b>${grams(r.byPerson[p.id])}</b></span>`).join('')}</div>${shoppingHints[r.id]?html`<p>${t(shoppingHints[r.id])}</p>`:''}</details></div>`}).join('')}</section>`).join(''):t('<div class="empty-state">Выбери хотя бы одного человека, чтобы собрать корзину.</div>')}</div><aside class="basket-summary"><h3>Общая корзина</h3><div class="summary-line"><span>Человек</span><b>${people.length}</b></div><div class="summary-line"><span>Дней в плане</span><b>${dates.length}</b></div><div class="summary-line"><span>Всего порций</span><b>${dates.length*4*people.length}</b></div><div class="summary-line"><span>Продуктов</span><b>${rows.length}</b></div><div class="summary-line"><span>Общий вес</span><b>${grams(total)}</b></div><div class="summary-line"><span>Уже куплено</span><b>${bought} из ${rows.length}</b></div><div class="tiny-bar" style="margin-bottom:20px"><span style="width:${rows.length?bought/rows.length*100:0}%"></span></div><button class="primary" id="copyBasket" ${rows.length?'':'disabled'}>${ico('copy')} Скопировать список</button><button class="secondary" id="exportBasket" ${rows.length?'':'disabled'}>${ico('download')} Скачать CSV</button><button class="secondary" id="clearBought">Снять отметки</button><p>Mercadona · Lidl · Aldi · DIA · bonÀrea. Испанские названия помогают искать продукт; наличие и состав уточняй в магазине.</p><p>Сумма сырых съедобных ингредиентов по каждому человеку, без округления до упаковок. Учти очистку и запас при покупке.</p><p>При изменении количества продукта отметка «куплено» сбрасывается для новой порции.</p></aside></div>`;}
function renderSettings(){const p=person(),estimate=estimateCalories(p);return html`${heading(t('Всё под вас'),t('Личные цели, общие блюда и удобные покупки на семью.'))}<div class="settings-grid"><div>${accountPanel()}<section class="settings-panel"><h3>Профиль: ${esc(p.name)}</h3><p>Калорийность не определяется только полом. Можно задать свою цель вручную или оценить её по весу, росту, возрасту и повседневной активности.</p><div class="profile-fields"><label>Имя<input type="text" data-profile-field="name" maxlength="40" value="${esc(p.name)}"></label><label>Пол для формулы<select data-profile-field="sex"><option value="male" ${p.sex==='male'?'selected':''}>Мужской</option><option value="female" ${p.sex==='female'?'selected':''}>Женский</option></select></label><label>Рост, см<input type="number" data-profile-field="height" min="130" max="220" value="${p.height??''}" placeholder="Твой рост"></label><label>Возраст, лет<input type="number" data-profile-field="age" min="18" max="100" value="${p.age??''}" placeholder="Твой возраст"></label><label>Вес, кг<input type="number" data-profile-field="weight" min="40" max="180" step="0.5" value="${p.weight}"></label><label>Активность<select data-profile-field="activity">${[[1.2,t('Мало движения')],[1.375,t('Лёгкая активность')],[1.55,t('Средняя активность')],[1.725,t('Высокая активность')]].map(([v,t])=>html`<option value="${v}" ${p.activity===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide-field">Корректировка к оценке поддержания<select data-profile-field="adjustment">${[[-.15,'−15%'],[0,t('Без корректировки')],[.1,'+10%']].map(([v,t])=>html`<option value="${v}" ${p.adjustment===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="toggle-row"><input type="checkbox" data-shopping-person="${p.id}" ${p.inShopping?'checked':''}><span>Учитывать ${esc(p.name)} в общей корзине</span></label><div class="estimate-box">${estimate?html`<div><small>Обмен в покое</small><b>${n(estimate.resting)} ккал</b></div><div><small>Поддержание с активностью</small><b>${n(estimate.maintenance)} ккал</b></div><div><small>С выбранной корректировкой</small><b>${n(estimate.target)} ккал</b></div><button class="primary" id="applyEstimate" ${estimate.inRange?'':'disabled'}>Применить ${n(estimate.target)} ккал</button>${estimate.inRange?'':t('<p>Оценка за диапазоном калькулятора. Цель можно обсудить со специалистом и задать вручную.</p>')}`:t('<p>Добавь рост и возраст, чтобы увидеть приблизительную оценку. Вес и текущая цель пока могут быть примерами.</p>')}</div><p class="estimate-note">Формула <a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">Миффлина — Сан Жеора</a> оценивает обмен в покое. Умножение на выбранную активность и корректировка дают ориентир для планирования, не точную норму. Применение оценки отключит добавку за тренировку, чтобы не учесть активность дважды. Оценка для взрослых, не для беременности и грудного вскармливания.</p></section><section class="settings-panel participant-danger"><div><h3>Удалить участника</h3><p>Убрать ${esc(p.name)} из активных профилей и общей корзины. Сначала появится окно подтверждения. Дневник можно будет восстановить.</p></div><button class="danger-button" data-remove-person="${p.id}" ${state.profiles.length===1?'disabled':''}>Удалить участника</button>${state.profiles.length===1?t('<small>Нужно оставить хотя бы одного участника.</small>'):''}</section>${archivedPeople()}<section class="settings-panel"><h3>Тренировки: ${esc(p.name)}</h3><p>Расписание и добавка индивидуальны. Если активность уже включена в твою цель калорий, оставь добавку равной нулю.</p><div class="training-days">${weekDays.map((day,i)=>html`<button data-training-day="${i}" class="${p.trainingDays.includes(i)?'active':''}" aria-pressed="${p.trainingDays.includes(i)}">${t(day)}</button>`).join('')}</div><label class="block" for="bonusInput" style="margin-top:20px">Добавка в тренировочный день</label><input type="number" id="bonusInput" min="0" max="1000" step="10" value="${p.bonus}"> <span class="muted">ккал</span></section><section class="settings-panel"><h3>Как готовить вместе</h3><p>Меню общее для семьи. Калорийность и граммовки рассчитываются отдельно для каждого профиля. В рецепте есть таблица порций и общий вес каждого ингредиента.</p><p>Курицу, овощи и гарнир удобно готовить вместе, а после приготовления делить каждую часть по указанным пропорциям. Все граммы в приложении — до приготовления.</p><p>Гречка заменена бурым рисом (arroz integral). Порция близка по калорийности, состав КБЖУ отличается и пересчитан.</p><button class="secondary" id="addPersonSettings" ${state.profiles.length>=8?'disabled':''}>Добавить ещё человека</button></section><section class="settings-panel"><h3>Цели и предпочтения</h3><label class="block" for="profileNote">Общие заметки</label><textarea id="profileNote" placeholder="Ваши цели, любимые продукты, на сколько дней готовить…">${esc(state.profileNote)}</textarea><button class="primary" id="saveNote" style="margin-top:12px">Сохранить заметку</button></section><section class="settings-panel"><h3>Данные и перенос</h3><p>После входа профили, дневники, покупки и собственные рецепты сохраняются в аккаунте Supabase. На устройстве остаётся копия для восстановления при потере связи. Старые резервные копии также можно импортировать: личные данные перейдут в первый профиль.</p><div class="settings-actions"><button class="primary" id="exportData">${ico('download')} Экспорт данных</button><button class="secondary" id="importData">Импорт из JSON</button><input hidden type="file" accept="application/json,.json" id="importFile"></div></section><section class="settings-panel"><h3>Ориентиры и точность</h3><p>Меню масштабируется до дневной цели каждого человека. КБЖУ приблизительные — конкретная упаковка может отличаться. Отметка съеденного сохраняет снимок личной порции.</p><p>Примеры калорийности не являются персональными рекомендациями. PDF с вашей программой пока недоступен.</p></section></div><aside class="side-stack">${calculator()}<section class="settings-panel"><h3>Покупки в Испании</h3><p>В корзине и её выгрузках рядом с каждым продуктом есть название на испанском. Под сложными позициями — пояснения для выбора.</p><p>Например, бурый рис — <span lang="es">arroz integral</span>, куриное филе — <span lang="es">pechuga de pollo</span>, индейка — <span lang="es">pechuga de pavo</span>.</p></section></aside></div>`;}
function render(){
 $('#languageSlot').innerHTML=languageSelect();syncLanguageControls();
 const logoutButton=$('#topLogout');if(logoutButton){logoutButton.hidden=!accountUser;logoutButton.innerHTML=ico('logout')+'<span>'+t('Выйти из аккаунта')+'</span>';}
 $('#nav').innerHTML=Object.entries(names).map(([id,title])=>html`<a href="#${id}" class="nav-item ${view===id?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${ico({day:'day',plan:'calendar',recipes:'book',basket:'basket',settings:'settings'}[id])}<span>${t(title)}</span>${id==='basket'?html`<span class="nav-count">${basket(dateRange(date,basketScope),state).length}</span>`:''}</a>`).join('');
 $('#crumb').textContent=t(names[view])+' · '+person().name;$('#helpBtn').innerHTML=ico('help');
 $('#view').innerHTML=profileBar()+({day:renderDay,plan:renderPlan,recipes:renderRecipes,basket:renderBasket,settings:renderSettings}[view])();
 $('.avatar').textContent=String(state.profiles.length);
 updateSave();bindCalculator();updateDemoNote();
}
function refreshPreservingFocus(){
 // Keep the calculator in the DOM so pointer capture survives continuous dragging.
 if(view==='day'){
  $('.stats-row').outerHTML=macroStats();
  $('.meal-grid').innerHTML=planDay(date,state).map(m=>mealCard(m)).join('');
  $('.mini-basket').outerHTML=miniBasket();
 }
 for(const [id,value] of [['weightRange',person().weight],['weightNumber',person().weight],['kcalRange',person().kcal],['kcalNumber',person().kcal]]){
  const field=document.getElementById(id);if(field)field.value=value;
 }
 const family=$('.family-summary');if(family)family.outerHTML=familySummary();
 $('.profile-switch')?.closest('.household-bar')?.replaceWith(htmlNode(profileBar()));
 updateDemoNote();
 const total=$('.calculation-total b');if(total)total.innerHTML=html`${n(dayTarget(date,state))} <small>ккал</small>`;
}
function htmlNode(html){const template=document.createElement('template');template.innerHTML=html;return template.content.firstElementChild;}
function updateDemoNote(){const note=$('.demo-note>span:nth-child(2)');note.innerHTML=state.profiles.some(p=>p.demo)?t('<b>Настройте ваши цели.</b> Цели в новых профилях — примеры. Проверь калорийность и внеси свои параметры и параметры жены.'):t('<b>Цели заданы вами.</b> PDF ещё недоступен; состав меню можно менять вручную.');}
function bindCalculator(){for(const id of ['weightRange','weightNumber','kcalRange','kcalNumber']){const field=document.getElementById(id);if(!field)continue;field.addEventListener(id.endsWith('Range')?'input':'change',event=>{const isWeight=id.startsWith('weight'),value=Number(event.target.value);if(!Number.isFinite(value)||value<(isWeight?40:1200)||value>(isWeight?180:5000)){toast(t('Значение за пределами диапазона'));render();return;}if(isWeight)Object.assign(person(),resizeWeight(person(),value));else{person().kcal=Math.round(value);delete person().weightBase;person().demo=false;}persist();refreshPreservingFocus();});}$('#linkWeight')?.addEventListener('change',event=>{person().linkWeight=event.target.checked;delete person().weightBase;persist();render();});}

function chooseMeal(id,key=date,slot=null){const recipe=recipeList().find(r=>r.id===id);if(!recipe)return;try{state=setMeal(state,key,slot??recipe.slot,id);persist();render();toast(html`Общее меню обновлено: ${fullDate(key)}`);}catch{toast(t('Выбери блюдо для того же приёма пищи'));}}
function openRecipe(id,key=date){
 const meal=portionForRecipe(id,key,state),house=householdRecipe(id,key,state),people=house.portions;
 const dialog=$('#recipeDialog');if(dialog.dataset){dialog.dataset.recipeId=id;dialog.dataset.recipeDate=key;}dialog.innerHTML=html`<button class="dialog-close" data-close="recipeDialog" aria-label="Закрыть">×</button>${photo(meal,true)}<div class="eyebrow">${t(slots[meal.slot])} · ${meal.time} МИНУТ · ${esc(person().name)}</div><h2 id="recipeTitle">${esc(mealText(meal,'title'))}</h2><p class="dialog-subtitle">${esc(mealText(meal,'subtitle'))}</p><div class="macro-pills">${[t('ккал'),t('г белка'),t('г жиров'),t('г углеводов')].map((label,i)=>html`<span>${n(meal.macros[i])} ${label}</span>`).join('')}</div>${personalPortionEditor(meal,key)}${omeletNote(meal)}<div class="recipe-view-tabs"><button class="${recipeScope==='person'?'active':''}" data-recipe-scope="person" data-scope-recipe="${id}" data-scope-date="${key}">Моя порция · ${esc(person().name)}</button><button class="${recipeScope==='family'?'active':''}" data-recipe-scope="family" data-scope-recipe="${id}" data-scope-date="${key}">Готовим вместе · ${people.length} чел.</button></div>${recipeScope==='family'?html`<section class="family-recipe"><h3>Ингредиенты для общей готовки</h3>${people.length?html`<div class="portion-table-wrap"><table class="portion-table"><thead><tr><th>Продукт</th>${people.map(({person:p})=>html`<th>${esc(p.name)}</th>`).join('')}<th>Всего</th></tr></thead><tbody>${Object.entries(house.ingredients).map(([food,g])=>html`<tr><td>${foodName(food)}<small lang="es">(${esc(spanishFor(state,food))})</small></td>${people.map(({meal:m})=>html`<td>${ingredientAmount(food,m.ingredients[food]||0)}</td>`).join('')}<td>${ingredientAmount(food,g)}</td></tr>`).join('')}</tbody><tfoot><tr><td>Калорийность порции</td>${people.map(({meal:m})=>html`<td>${n(m.macros[0])} ккал</td>`).join('')}<td>${n(house.macros[0])} ккал</td></tr></tfoot></table></div><p class="subtle-info">Взвешивайте продукты до готовки и соблюдайте индивидуальные количества из таблицы. Ночные завтраки и йогурты удобнее сразу готовить в отдельных баночках. При общей готовке доли считайте для каждого ингредиента отдельно; готовый вес изменится.</p>`:t('<p class="subtle-info">В корзине не выбран ни один человек. Добавь участников в настройках.</p>')}</section><h3 class="method-title">Как приготовить</h3><ol class="recipe-steps">${meal.steps.map(step=>html`<li>${esc(meal.custom?step:t(step))}</li>`).join('')}</ol>`:html`<div class="recipe-columns"><section><h3>Состав для ${esc(person().name)}</h3><ul class="ingredients">${Object.entries(meal.ingredients).map(([food,g])=>html`<li><span>${foodName(food)}<small lang="es">(${esc(spanishFor(state,food))})</small></span><span>${ingredientAmount(food,g)}</span></li>`).join('')}</ul><p class="subtle-info">Вес сырого продукта. Вода и приправы — по вкусу.</p></section><section><h3>Как приготовить</h3><ol class="recipe-steps">${meal.steps.map(step=>html`<li>${esc(meal.custom?step:t(step))}</li>`).join('')}</ol></section></div>`}${meal.video?html`<a class="secondary" href="${meal.video}" target="_blank" rel="noopener noreferrer">${ico('play')} ${meal.search?t('Найти видео на YouTube'):t('Смотреть на YouTube')}</a><p class="video-note">${t(meal.channel)}. ${meal.search?t('Это ссылка на поиск, конкретное видео ещё не выбрано.'):t('Видео показывает технику приготовления; для меню используй граммовки выше.')}</p>`:''}${ingredientSources(meal)}<p class="photo-credit">Иллюстрация: <a href="${mealPhotos[meal.image].source}" target="_blank" rel="noopener noreferrer">${t(mealPhotos[meal.image].credit)}</a>. Подача может отличаться.</p><div class="recipe-footer"><button class="primary" data-use="${meal.id}" data-use-date="${key}" data-close-after>В общее меню на ${shortDate(key)}</button><button class="secondary" data-close="recipeDialog">Закрыть</button></div>`;
 if(!dialog.open)dialog.showModal();
}

function ingredientAmount(food,g){let detail='';if(food==='egg')detail=html`≈ ${(g/50).toLocaleString(locale(),{maximumFractionDigits:1})} целых яиц`;if(food==='eggwhite')detail=html`≈ ${(g/33).toLocaleString(locale(),{maximumFractionDigits:1})} доп. белков`;return html`${grams(g)}${detail?html`<small class="egg-equivalent">${detail}</small>`:''}`;}
function omeletNote(meal){if(!meal.ingredients.eggwhite)return '';const eggs=(meal.ingredients.egg||0)/50,added=meal.ingredients.eggwhite/33;return html`<p class="omelet-note">В твоей порции примерно ${eggs.toLocaleString(locale(),{maximumFractionDigits:1})} целых яиц и ${added.toLocaleString(locale(),{maximumFractionDigits:1})} дополнительных белков из бутылки. Всего около ${Math.round(eggs+added)} белков, желтки — только из целых яиц. Пересчёт по штукам ориентировочный; точнее взвешивать.</p>`;}
function personalPortionEditor(meal,key){const group=portionGroups[meal.portionGroup];if(!group)return '';const amounts=recipeAmounts(meal,person());return html`<details class="portion-editor"><summary>Настроить мою порцию · ${esc(person().name)}</summary><p>Эти количества сохранятся для твоих блюд «${t(group.label)}» во все даты и не будут масштабироваться. Остальные ингредиенты дня подстроятся под цель калорий.</p><div class="portion-fields">${Object.entries(group.fields).map(([food,rule])=>html`<label>${rule.wholeEggs?t('Целые яйца, шт.'):html`${foodName(food)}, г`}<input type="number" data-portion-food="${food}" data-portion-eggs="${!!rule.wholeEggs}" value="${rule.wholeEggs?amounts[food]/50:amounts[food]}" min="${rule.wholeEggs?rule.min/50:rule.min}" max="${rule.wholeEggs?rule.max/50:rule.max}" step="${rule.wholeEggs?1:rule.step}"></label>`).join('')}</div><p class="portion-tip">${meal.custom?t('<span> · Мой рецепт</span>'):''}${meal.portionGroup==='overnight'?t('В стартовом примере: молоко 200 г для «Я», 150 г для «Жена», порошок по 15 г. 15 г — вес порошка, а не чистого белка.'):meal.portionGroup==='evening'?t('Стартовый пример: йогурт 125 г и cottage 87,5 г каждому — одна упаковка cottage 175 г на двоих.'):t('Стартовые количества — редактируемые примеры. Жидкий белок добавляется к белкам, которые уже есть в целых яйцах.')}</p><button class="primary" data-save-portion="${meal.portionGroup}" data-portion-recipe="${meal.id}" data-portion-date="${key}">Сохранить мои пропорции</button></details>`;}
function ingredientSources(meal){const sources=Object.keys(productSources).filter(food=>Object.hasOwn(meal.ingredients,food));if(!sources.length)return '';return html`<details class="ingredient-sources"><summary>Продукты: состав и источники</summary>${sources.map(food=>{const source=productSources[food];return html`<p><a href="${source.url}" target="_blank" rel="noopener noreferrer">${t(source.label)}</a><br>${t(source.note)}${source.packUrl?html` <a href="${source.packUrl}" target="_blank" rel="noopener noreferrer">Упаковка 175 г</a>.`:''}</p>`}).join('')}<p>Доступность в конкретном магазине Mercadona не проверена. Для мюсли, йогурта и протеина используются примерные КБЖУ: ориентируйся на свою упаковку.</p></details>`;}
function archivedPeople(){return state.archivedProfiles.length?html`<section class="settings-panel archived-people"><h3>Удалённые участники</h3><p>Можно вернуть профиль вместе с дневником, водой и личными настройками.</p>${state.archivedProfiles.map(entry=>html`<div><span>${esc(entry.profile.name)}</span><button class="secondary" data-restore-person="${entry.profile.id}" ${state.profiles.length>=8?'disabled':''}>Восстановить</button></div>`).join('')}</section>`:'';}
function openRemoval(id){const p=state.profiles.find(p=>p.id===id);if(!p)return;if(state.profiles.length<=1){toast(t('Нужно оставить хотя бы одного участника'));return;}pendingRemoval=id;const dialog=$('#removePersonDialog');dialog.innerHTML=html`<div class="confirmation-icon">×</div><h2 id="removePersonTitle">Удалить участника «${esc(p.name)}»?</h2><p>Вы уверены, что хотите удалить участника?</p><p class="muted">Его порции исчезнут из общей корзины, и список покупок пересчитается. Профиль и дневник можно восстановить в настройках.</p><div class="confirmation-actions"><button class="secondary" data-close="removePersonDialog" autofocus>Отмена</button><button class="danger-button" id="confirmRemovePerson">Удалить участника</button></div>`;dialog.showModal();}
function replacementResults(){if(!replacementContext)return '';const {key,slot}=replacementContext,current=planDay(key,state)[slot],options=searchReplacements(state,key,slot,replacementQuery);return options.length?options.map(meal=>html`<button class="replacement-option ${meal.id===current.id?'current':''}" data-replace-choice="${meal.id}" ${meal.id===current.id?'disabled':''}><img src="${img(meal)}" alt="" loading="lazy" referrerpolicy="no-referrer"><span><small>${t(slots[slot])} · ${meal.time} мин</small><b>${esc(mealText(meal,'title'))}</b><span>${n(meal.macros[0])} ккал для ${esc(person().name)}</span></span><span class="replacement-action">${meal.id===current.id?t('В меню'):t('Выбрать')}</span></button>`).join(''):t('<div class="empty-state">Ничего не найдено. Попробуй «омлет», «мюсли», «сыр» или название продукта.</div>');}
function openReplacement(slot,key=date){if(!Number.isInteger(slot)||slot<0||slot>3)return;replacementContext={key,slot};replacementQuery='';const dialog=$('#replacementDialog');dialog.innerHTML=html`<button class="dialog-close" data-close="replacementDialog" aria-label="Закрыть">×</button><div class="eyebrow">${fullDate(key)} · ОБЩЕЕ МЕНЮ</div><h2 id="replacementTitle">Выбрать ${[t('завтрак'),t('обед'),t('ужин'),t('перекус')][slot]}</h2><p class="replacement-intro">Показаны только блюда категории «${t(slots[slot])}». Выбор изменит этот приём пищи на выбранную дату для всей семьи.</p><label class="search replacement-search">${ico('search')}<input id="replacementSearch" placeholder="Найти блюдо или продукт…" aria-label="Поиск блюда для замены" autofocus></label><div id="replacementResults" class="replacement-list">${replacementResults()}</div><p class="subtle-info">Цель калорий каждого сохраняется: граммовки остальных блюд дня тоже пересчитаются. Уже съеденные приёмы в дневнике останутся прежними.</p>`;dialog.showModal();$('#replacementSearch')?.focus({preventScroll:true});}

function accountPanel(){if(!accountUser)return '';return html`<section class="settings-panel account-panel"><h3>Мой аккаунт</h3><p>${esc(accountUser.email||'')}</p><p>${cloudStatus==='conflict'?t('Облачный план изменён на другом устройстве. Текущие изменения сохранены здесь. Можно выгрузить JSON или загрузить облачную версию.'):cloudStatus==='offline'?t('Изменения остаются на этом устройстве. Повтори синхронизацию, когда появится сеть.'):t('Профили, дневник, покупки и рецепты синхронизируются с базой.')}</p><div class="settings-actions"><button class="secondary" id="retrySync">Повторить синхронизацию</button><button class="secondary" id="reloadCloud">Загрузить облачную версию</button><button class="secondary" id="recoverLocal">Вернуть копию до загрузки</button><button class="secondary" id="importLegacy">Перенести прежний рацион</button><button class="secondary" id="accountLogout">${ico('logout')} Выйти из аккаунта</button></div></section>`;}
function captureDraft(){if(!recipeDraft)return;recipeDraft.title=$('#customTitle').value;recipeDraft.slot=Number($('#customSlot').value);recipeDraft.time=Number($('#customTime').value);recipeDraft.steps=$('#customSteps').value;recipeDraft.paste=$('#ingredientPaste').value;for(const input of document.querySelectorAll('[data-editor-food]')){const i=Number(input.dataset.editorFood);if(recipeDraft.rows[i])recipeDraft.rows[i].id=input.value;}for(const input of document.querySelectorAll('[data-editor-grams]')){const i=Number(input.dataset.editorGrams);if(recipeDraft.rows[i])recipeDraft.rows[i].grams=Number(input.value);}}
function editorStatus(message,error=false){const node=$('#customRecipeStatus');node.textContent=message;node.classList.toggle('error',error);}
function editorNutrition(){const ingredients={};for(const row of recipeDraft.rows)if(catalog()[row.id]&&Number.isFinite(row.grams)&&row.grams>0)ingredients[row.id]=(ingredients[row.id]||0)+row.grams;const values=recipeMacros(ingredients,state);return html`<div class="macro-pills">${[t('ккал'),t('г белка'),t('г жиров'),t('г углеводов')].map((label,i)=>html`<span>${n(values[i])} ${label}</span>`).join('')}</div><p class="editor-hint">КБЖУ для всей указанной закладки. В плане она масштабируется под выбранную цель калорий.</p>`;}
function renderEditor(){const draft=recipeDraft,dialog=$('#customRecipeDialog');dialog.innerHTML=html`<button class="dialog-close" data-close="customRecipeDialog" aria-label="Закрыть">×</button><div class="eyebrow">ТВОЯ КУХНЯ</div><h2 id="customRecipeTitle">Новый рецепт</h2><p class="replacement-intro">Добавь состав в граммах. Калории и БЖУ посчитаются по продуктам; шаги можно написать самому или подготовить с AI.</p><div class="profile-fields"><label class="wide-field">Название<input id="customTitle" maxlength="120" value="${esc(draft.title)}" placeholder="Например, мой омлет"></label><label>Приём пищи<select id="customSlot">${slots.map((name,i)=>html`<option value="${i}" ${draft.slot===i?'selected':''}>${t(name)}</option>`).join('')}</select></label><label>Время, минут<input id="customTime" type="number" min="1" max="240" value="${draft.time}"></label></div><section class="editor-section"><h3>Быстро добавить состав</h3><textarea id="ingredientPaste" placeholder="Куриное филе 200 г&#10;Рис 80 г&#10;Помидоры 100 г">${esc(draft.paste||'')}</textarea><p class="editor-hint">Каждый продукт с новой строки, вес в г или кг. Неизвестные продукты добавь ниже по этикетке.</p><button class="secondary" id="parseIngredients">Разобрать ингредиенты</button></section><section class="editor-section"><h3>Ингредиенты</h3><div class="editor-ingredients">${draft.rows.map((row,i)=>html`<div><select data-editor-food="${i}" aria-label="Продукт ${i+1}">${Object.entries(catalog()).map(([id,f])=>html`<option value="${id}" ${id===row.id?'selected':''}>${foodName(id)} (${esc(spanishFor(state,id))})</option>`).join('')}</select><label><input type="number" min="0.1" max="5000" step="0.1" value="${row.grams}" data-editor-grams="${i}" aria-label="Граммы продукта ${i+1}"><span>г</span></label><button data-editor-remove="${i}" aria-label="Убрать ингредиент ${i+1}">×</button></div>`).join('')}</div><button class="secondary" id="addIngredient">+ Ингредиент</button><div id="editorMacros">${editorNutrition()}</div><details class="custom-food-panel"><summary>Продукта нет в справочнике</summary><p class="editor-hint">Перенеси КБЖУ с упаковки на 100 г. Без этих данных расчёт был бы догадкой.</p><div class="profile-fields"><label>Название<input id="foodRu" maxlength="120" placeholder="Название продукта"></label><label>По-испански<input id="foodEs" maxlength="160" placeholder="Nombre en español"></label>${[['Kcal',t('Ккал'),1000],['Protein',t('Белки, г'),100],['Fat',t('Жиры, г'),100],['Carbs',t('Углеводы, г'),100]].map(([id,label,max])=>html`<label>${label}<input id="food${id}" type="number" min="0" max="${max}" step="0.1" placeholder="На 100 г"></label>`).join('')}</div><button class="secondary" id="addCustomFood">Сохранить продукт</button></details></section><section class="editor-section"><h3>Как приготовить</h3><textarea id="customSteps" placeholder="Каждый шаг с новой строки…">${esc(draft.steps)}</textarea><details class="recipe-ai-panel"><summary>Помочь с шагами через AI</summary><p>Экспериментальный локальный помощник Qwen3 0.6B. Первый запуск скачает веса модели с Hugging Face — это могут быть сотни мегабайт. Нужен WebGPU. Текст обрабатывается на устройстве; проверь черновик перед сохранением.</p><button class="secondary" id="aiRecipe">Загрузить модель и подготовить шаги</button><p class="editor-hint">AI не считает КБЖУ и не заменяет проверку приготовления. Рецепт можно сохранить без модели.</p></details></section><p id="customRecipeStatus" role="status" aria-live="polite"></p><div class="recipe-footer"><button class="primary" id="saveCustomRecipe">Сохранить рецепт</button><button class="secondary" data-close="customRecipeDialog">Отмена</button></div>`;if(!dialog.open)dialog.showModal();}
function openRecipeEditor(){editorEpoch++;recipeDraft={title:'',slot:0,time:15,steps:'',paste:'',rows:[]};renderEditor();}

function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function basketText(){const dates=dateRange(date,basketScope),rows=basket(dates,state);return html`Список покупок · ${fullDate(dates[0])}${dates.length>1?html` — ${fullDate(dates.at(-1))}`:''}\nДля: ${selectedPeople().map(p=>p.name).join(', ')}\n\n${rows.map(r=>html`${state.bought[basketKey(dates,r)]?'☑':'☐'} ${localizedFood(r.id)} (${r.spanish}) — ${grams(r.grams)}`).join('\n')}\n\nВес сырых съедобных продуктов. Без округления до упаковок.`;}
function exportBasket(){const rows=basket(dateRange(date,basketScope),state),people=selectedPeople(),header=[t('Категория'),t('Продукт'),t('Название на испанском'),t('Всего (г)'),...people.map(p=>html`${p.name} (г)`)];const csv=[header,...rows.map(r=>[t(r.category),localizedFood(r.id),r.spanish,r.grams,...people.map(p=>r.byPerson[p.id])])].map(row=>row.map(v=>html`"${String(v).replaceAll('"','""')}"`).join(';')).join('\r\n');download(html`ration-shopping-${date}.csv`,'\uFEFF'+csv,'text/csv;charset=utf-8');toast(t('Список покупок скачан'));}
function validImport(data){try{migrateState(data);return true}catch{return false;}}

document.addEventListener('click',async event=>{
 const btn=event.target.closest('button,a[data-nav]');if(!btn)return;
 if(btn.id==='accountLogout'||btn.id==='topLogout'){if(!accountController||btn.disabled)return;btn.disabled=true;try{await accountController.logout();}finally{btn.disabled=false;}return;}
 if(btn.id==='retrySync'){await accountController?.retry();return;}
 if(btn.id==='reloadCloud'){await accountController?.reload();return;}
 if(btn.id==='recoverLocal'){accountController?.recover();return;}
 if(btn.id==='importLegacy'){accountController?.importLegacy();return;}
 if(btn.id==='newRecipe'){openRecipeEditor();return;}
 if(btn.id==='addIngredient'){captureDraft();if(recipeDraft.rows.length>=30){editorStatus(t('До 30 ингредиентов в рецепте.'),true);return;}recipeDraft.rows.push({id:'oats',grams:50});renderEditor();return;}
 if(btn.dataset.editorRemove!==undefined){captureDraft();recipeDraft.rows.splice(Number(btn.dataset.editorRemove),1);renderEditor();return;}
 if(btn.id==='parseIngredients'){captureDraft();const result=parseIngredientText(recipeDraft.paste,state);if(result.unresolved.length){editorStatus(t('Нужно уточнить продукт или вес: ')+result.unresolved.join('; '),true);return;}if(!result.rows.length){editorStatus(t('Добавь продукты и вес в граммах.'),true);return;}recipeDraft.rows=result.rows;renderEditor();return;}
 if(btn.id==='addCustomFood'){
  if(Object.keys(state.customFoods).length>=500){editorStatus(t('До 500 собственных продуктов.'),true);return;}
  captureDraft();const name=$('#foodRu').value.trim(),spanish=$('#foodEs').value.trim(),ids=['Kcal','Protein','Fat','Carbs'];
  const values=ids.map(id=>$('#food'+id).value===''?NaN:Number($('#food'+id).value));
  if(!name||name.length>120||!spanish||spanish.length>160||!values.every((v,i)=>Number.isFinite(v)&&v>=0&&v<=(i===0?1000:100))){editorStatus(t('Заполни названия и все значения КБЖУ на 100 г.'),true);return;}
  const id='food-'+crypto.randomUUID();state={...state,customFoods:{...state.customFoods,[id]:{food:[name,'Свои продукты',...values],spanish}}};persist();recipeDraft.rows.push({id,grams:100});renderEditor();return;
 }
 if(btn.id==='saveCustomRecipe'){captureDraft();try{const recipe=createCustomRecipe(recipeDraft,state,'recipe-'+crypto.randomUUID());state={...state,customRecipes:[...state.customRecipes,recipe]};validateState(state);persist();$('#customRecipeDialog').close();recipeFilter=String(recipe.slot);searchTerm='';navigate('recipes');toast(t('Рецепт сохранён: можно добавить в меню'));}catch{editorStatus(t('Проверь название, граммовки, время и шаги приготовления.'),true);}return;}
 if(btn.id==='aiRecipe'){
  captureDraft();if(recipeDraft.title.trim().length<2||!recipeDraft.rows.length){editorStatus(t('Сначала добавь название и ингредиенты.'),true);return;}
  const mine=editorEpoch;btn.disabled=true;
  try{const output=await draftRecipeWithAI({title:recipeDraft.title,ingredients:recipeDraft.rows.map(row=>({name:catalog()[row.id][0],grams:row.grams})),onProgress:text=>{if(mine===editorEpoch)editorStatus(text);}});if(mine===editorEpoch&&$('#customRecipeDialog').open){recipeDraft.steps=output.steps.join('\n');recipeDraft.time=output.time;renderEditor();editorStatus(t('Черновик готов. Проверь и отредактируй шаги перед сохранением.'));}}
  catch(error){if(mine===editorEpoch)editorStatus(String(error.message||t('Модель недоступна. Добавь шаги вручную.')),true);}finally{if(btn.isConnected)btn.disabled=false;}return;
 }
 if(btn.dataset.removePerson){openRemoval(btn.dataset.removePerson);return;}
 if(btn.id==='confirmRemovePerson'){if(!pendingRemoval)return;try{state=removeProfile(state,pendingRemoval);pendingRemoval=null;$('#removePersonDialog').close();persist();render();toast(t('Участник удалён. Вернуть можно в настройках.'));}catch{toast(t('Не удалось удалить участника'));}return;}
 if(btn.dataset.restorePerson){try{state=restoreProfile(state,btn.dataset.restorePerson);persist();render();toast(t('Участник восстановлен вместе с дневником'));}catch{toast(t('Можно включить до восьми участников'));}return;}
 if(btn.dataset.savePortion){
  const values={};for(const input of document.querySelectorAll('#recipeDialog [data-portion-food]'))values[input.dataset.portionFood]=Number(input.value)*(input.dataset.portionEggs==='true'?50:1);
  try{state=setRecipeAmounts(state,person().id,btn.dataset.savePortion,values);persist();render();openRecipe(btn.dataset.portionRecipe,btn.dataset.portionDate);toast(t('Личные пропорции сохранены; корзина пересчитана'));}catch{toast(t('Проверь количества и допустимые диапазоны'));}return;
 }
 if(btn.dataset.replaceChoice){if(!replacementContext)return;const {key,slot}=replacementContext;const chosen=recipeList().find(r=>r.id===btn.dataset.replaceChoice);if(!chosen||chosen.slot!==slot){toast(t('Нужна замена из той же категории'));return;}chooseMeal(chosen.id,key,slot);$('#replacementDialog').close();replacementContext=null;return;}
 if(btn.dataset.person){state.activeProfileId=btn.dataset.person;persist();render();return;}
 if(btn.id==='addPerson'||btn.id==='addPersonSettings'){if(state.profiles.length>=8)return;const id='person-'+crypto.randomUUID().slice(0,8),p=makeProfile(id,html`Участник ${state.profiles.length+1}`);state.profiles.push(p);state.activeProfileId=id;persist();navigate('settings');toast(t('Новый профиль: настрой цель и параметры'));return;}
 if(btn.dataset.recipeScope){recipeScope=btn.dataset.recipeScope;openRecipe(btn.dataset.scopeRecipe,btn.dataset.scopeDate);return;}
 if(btn.id==='applyEstimate'){const estimate=estimateCalories(person());if(!estimate?.inRange)return;person().kcal=estimate.target;person().bonus=0;person().linkWeight=false;person().demo=false;delete person().weightBase;persist();render();toast(t('Личная цель обновлена; добавка за тренировку — 0'));return;}
 if(btn.dataset.nav){event.preventDefault();navigate(btn.dataset.nav);return;}
 if(btn.dataset.close){document.getElementById(btn.dataset.close).close();return;}
 if(btn.dataset.date){date=btn.dataset.date;render();return;}
 if(btn.dataset.openDay){date=btn.dataset.openDay;navigate('day');return;}
 if(btn.dataset.step){const step=Number(btn.dataset.step),scope=view==='plan'?planScope:view==='basket'?basketScope:'day';if(scope==='month'){const d=parseDate(date);d.setDate(1);d.setMonth(d.getMonth()+step);date=localDate(d);}else date=addDays(date,step*(scope==='week'?7:1));render();return;}
 if(btn.dataset.period){const period=btn.dataset.period;if(period==='day')navigate('day');else{planScope=period;navigate('plan');}return;}
 if(btn.dataset.basketScope){basketScope=btn.dataset.basketScope;render();return;}
 if(btn.dataset.basketPeriod){basketScope=btn.dataset.basketPeriod;navigate('basket');return;}
 if(btn.dataset.recipe){openRecipe(btn.dataset.recipe,btn.dataset.recipeDate||date);return;}
 if(btn.dataset.use){chooseMeal(btn.dataset.use,btn.dataset.useDate||date);if(btn.hasAttribute('data-close-after'))$('#recipeDialog').close();return;}
 if(btn.hasAttribute('data-log')){const slot=Number(btn.dataset.log),key=html`${date}:${slot}`;if(person().logged[key])delete person().logged[key];else{const meal=planDay(date,state)[slot];person().logged[key]={id:meal.id,title:meal.title,macros:[...meal.macros],ingredients:{...meal.ingredients},at:new Date().toISOString()};}persist();render();return;}
 if(btn.hasAttribute('data-swap')){openReplacement(Number(btn.dataset.swap));return;}
 if(btn.hasAttribute('data-toggle-training')){person().trainingOverrides[date]=!isTraining(date,state);persist();render();return;}
 if(btn.hasAttribute('data-water')){const amount=Number(btn.dataset.water);person().water[date]=amount===0?0:Math.min(20000,Math.max(0,(person().water[date]||0)+amount));persist();render();return;}
 if(btn.hasAttribute('data-filter')){recipeFilter=btn.dataset.filter;render();return;}
 if(btn.hasAttribute('data-training-settings')){navigate('settings');return;}
 if(btn.hasAttribute('data-training-day')){const day=Number(btn.dataset.trainingDay);person().trainingDays=person().trainingDays.includes(day)?person().trainingDays.filter(d=>d!==day):[...person().trainingDays,day].sort();persist();render();return;}
 if(btn.id==='helpBtn'){$('#helpDialog').showModal();return;}
 if(btn.id==='noteSettings'){navigate('settings');return;}
 if(btn.id==='copyBasket'){const text=basketText();try{await navigator.clipboard.writeText(text);toast(t('Список покупок скопирован'));}catch{download(html`ration-shopping-${date}.txt`,text,'text/plain;charset=utf-8');toast(t('Список сохранён текстовым файлом'));}return;}
 if(btn.id==='exportBasket'){exportBasket();return;}
 if(btn.id==='clearBought'){const dates=dateRange(date,basketScope);for(const r of basket(dates,state))delete state.bought[basketKey(dates,r)];persist();render();toast(t('Отметки покупок сняты'));return;}
 if(btn.id==='saveNote'){state.profileNote=$('#profileNote').value;persist();toast(t('Заметка сохранена'));return;}
 if(btn.id==='exportData'){download(html`ration-backup-${date}.json`,JSON.stringify(state,null,2),'application/json');toast(t('Резервная копия скачана'));return;}
 if(btn.id==='importData'){$('#importFile').click();return;}
});
document.addEventListener('change',async event=>{
 const input=event.target;
 if(input.hasAttribute('data-language')){setLanguage(input.value);return;}
 if(input.hasAttribute('data-editor-food')){captureDraft();$('#editorMacros').innerHTML=editorNutrition();return;}
 if(input.id==='calculatorPerson'){state.activeProfileId=input.value;persist();render();return;}
 if(input.hasAttribute('data-shopping-person')){const p=state.profiles.find(p=>p.id===input.dataset.shoppingPerson);if(p){p.inShopping=input.checked;persist();render();}return;}
 if(input.hasAttribute('data-profile-field')){
  const field=input.dataset.profileField,p=person();let value=input.value;
  if(['height','age','weight','activity','adjustment'].includes(field))value=value===''?null:Number(value);
  const valid=field==='name'?typeof value==='string'&&value.trim().length>0&&value.length<=40:field==='sex'?['male','female'].includes(value):field==='height'?value===null||Number.isFinite(value)&&value>=130&&value<=220:field==='age'?value===null||Number.isInteger(value)&&value>=18&&value<=100:field==='weight'?Number.isFinite(value)&&value>=40&&value<=180:field==='activity'?[1.2,1.375,1.55,1.725].includes(value):field==='adjustment'?[-.15,0,.1].includes(value):false;
  if(!valid){toast(t('Проверь введённое значение'));render();return;}
  if(field==='weight')Object.assign(p,resizeWeight(p,value));else p[field]=field==='name'?value.trim():value;
  persist();render();return;
 }

 if(input.id==='selectedDate'&&/^\d{4}-\d{2}-\d{2}$/.test(input.value)){date=input.value;render();}
 if(input.hasAttribute('data-buy')){const dates=dateRange(date,basketScope),item=basket(dates,state).find(r=>r.id===input.dataset.buy);if(item){state.bought[basketKey(dates,item)]=input.checked;persist();render();}}
 if(input.id==='bonusInput'){const value=Number(input.value);if(Number.isFinite(value)&&value>=0&&value<=1000){person().bonus=Math.round(value);persist();render();}else{toast(t('Укажи значение от 0 до 1 000'));render();}}
 if(input.id==='importFile'&&input.files[0]){try{if(input.files[0].size>3000000)throw Error();const data=JSON.parse(await input.files[0].text());if(!validImport(data))throw Error();const backup=JSON.stringify(state);sessionStorage.setItem('ration-before-import',backup);state=migrateState(data);persist();render();toast(t('Данные импортированы'));}catch{toast(t('Не удалось прочитать корректную копию Рациона'));input.value='';}}
});
document.addEventListener('input',event=>{if(event.target.hasAttribute?.('data-editor-grams')){captureDraft();$('#editorMacros').innerHTML=editorNutrition();}if(event.target.id==='replacementSearch'){replacementQuery=event.target.value;$('#replacementResults').innerHTML=replacementResults();}if(event.target.id==='recipeSearch'){searchTerm=event.target.value;$('#recipesGrid').innerHTML=recipeResults();}});
document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement){event.target.hidden=true;event.target.closest('.meal-image,.dialog-image')?.classList.add('photo-unavailable');}},true);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(Object.hasOwn(names,next)&&view!==next){view=next;render();}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
const localizeStatic=captureStaticCopy();localizeStatic();
document.addEventListener('ration:language',()=>{
 localizeStatic();
 if(accountUser){state.language=getLanguage();persist();render();}else if(!accountController)render();
 accountController?.refreshLanguage();
 const recipeDialog=$('#recipeDialog');if(recipeDialog?.open&&recipeDialog.dataset?.recipeId)openRecipe(recipeDialog.dataset.recipeId,recipeDialog.dataset.recipeDate);
});
if(document.getElementById('authRoot')?.dataset?.cloudAuth==='true'){
 accountController=startAccountController({getState:()=>state,applyState:next=>{state=next;if(accountUser){setLanguage(state.language||getLanguage(),{notify:false});state.language=getLanguage();localizeStatic();}render();},onUser:user=>{accountUser=user;if(!user){editorEpoch++;recipeDraft=null;for(const dialog of document.querySelectorAll('dialog'))if(dialog.open)dialog.close();}},onStatus:status=>{cloudStatus=status;updateSave();},notify:toast,legacyKey:storageKey});
}else render();
